public sealed class BookingGateway {
    private readonly HttpClient _http;
    public BookingGateway(HttpClient http) => _http = http;

    public async Task<IReadOnlyList<Slot>> SlotsAsync(TimeSpan len, CancellationToken ct) {
        var raw = await _http.GetFromJsonAsync<List<ForeignSlot>>(
            $"/availableSlots?equipmentCode=BFSN&minutes={len.TotalMinutes}", ct);
        return raw?.Select(ToSlot).ToList()
               ?? throw new GatewayException("empty slot response");  // foreign -> domestic
    }
}
